export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = [];
  let allThresholdsPassed = true;

  Object.entries(thresholds).forEach(([metricId, minScore]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const metricScore = metric?.score;
    const passed = metricScore !== null && metricScore !== undefined && metricScore >= minScore;

    if (!passed) {
      allThresholdsPassed = false;
    }

    thresholdResults.push({
      metric: metricId,
      min: minScore,
      score: metricScore,
      passed
    });
  });

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

