import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Import frai-core
const fraiCorePath = '/private/tmp/100-tricks-runs/d08/with/h2-eval-thresholds/r1/packages/frai-core/src/eval/index.js';
const { generateReport, runEvaluations } = await import(fraiCorePath);

console.log('Testing edge cases...\n');

// Test 1: Multiple thresholds, some pass some fail
console.log('Test 1: Multiple thresholds with mixed results');
const evaluations = runEvaluations({
  outputs: ['a', 'b'],
  references: ['a', 'b']
});

const report1 = generateReport({
  evaluations,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: {
    exact_match: 0.5,  // should pass (score is 1)
    toxicity: 0.9      // should fail (score is 0)
  }
});

console.log('- exact_match threshold (0.5): ', report1.thresholds[0].passed ? 'PASS' : 'FAIL');
console.log('- toxicity threshold (0.9): ', report1.thresholds[1].passed ? 'PASS' : 'FAIL');
console.log('- Overall passed: ', report1.passed);

// Test 2: Threshold with null score (no references)
console.log('\nTest 2: Threshold on metric with null score');
const evaluations2 = runEvaluations({
  outputs: ['hello'],
  references: []
});

const report2 = generateReport({
  evaluations: evaluations2,
  outputsPath: '/tmp/out.json',
  referencesPath: null,
  thresholds: { exact_match: 0.5 }
});

console.log('- exact_match score: ', report2.thresholds[0].score);
console.log('- Threshold passed: ', report2.thresholds[0].passed);

// Test 3: Threshold value edge cases
console.log('\nTest 3: Threshold at boundary values');
const evaluations3 = runEvaluations({
  outputs: ['x'],
  references: ['x']
});

const report3a = generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 1.0 }
});

const report3b = generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 0.0 }
});

const report3c = generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: { exact_match: 1.0000001 }
});

console.log('- Threshold = 1.0 (score 1.0): ', report3a.thresholds[0].passed ? 'PASS' : 'FAIL');
console.log('- Threshold = 0.0 (score 1.0): ', report3b.thresholds[0].passed ? 'PASS' : 'FAIL');
console.log('- Threshold = 1.0000001 (score 1.0): ', report3c.thresholds[0].passed ? 'PASS' : 'FAIL');

console.log('\n✓ All edge case tests completed');

